from datetime import datetime


def _ts(value):
    """Turn updated_at into something comparable; ISO strings are parsed when possible."""
    if isinstance(value, str):
        try:
            return datetime.fromisoformat(value.replace("Z", "+00:00"))
        except ValueError:
            return value
    return value


def merge_attendance(records):
    """Keep one record per (player, date): the one with the latest updated_at.

    On a tie, the record appearing later in the list wins (a retried upload).
    Output order follows the first appearance of each (player, date) pair.
    """
    kept = {}
    for rec in records:
        key = (rec["player"], rec["date"])
        current = kept.get(key)
        if current is None or _ts(rec["updated_at"]) >= _ts(current["updated_at"]):
            kept[key] = rec
    return list(kept.values())
